(()=>{'use strict';const mixed=['Sweet Bundles','Build Your Own Treat Box'];const cookiePrices={1:5,2:9,4:17,6:24};const buildPrices={4:18,6:26,8:34,12:49};const bundles=[{name:'Sweet Duo',cakes:1,bars:1,price:9},{name:'Sweet 4',cakes:2,bars:2,price:17},{name:'Treat Box',cakes:3,bars:2,price:22}];let activeBundle=0,buildSize=4,mixSelected={},mixFilter='all';const originalRender=render;const originalTabs=renderTabs;function total(){return Object.values(mixSelected).reduce((a,n)=>a+n,0)}function selectedBy(type){return catalog.filter(x=>x.type===type).reduce((a,x)=>a+(mixSelected[x.id]||0),0)}function reset(){mixSelected={}}function mixRender(){const isBundle=category==='Sweet Bundles',item=isBundle?bundles[activeBundle]:null,limit=isBundle?item.cakes+item.bars:buildSize,price=isBundle?item.price:buildPrices[buildSize];const tabs=document.getElementById('tabs');tabs.innerHTML=['Mini Cakes','8×8 Cakes','Cookie Bars','Sweet Bundles','Build Your Own Treat Box','Dirty Sodas'].map(t=>'<button class="tab '+(t===category?'active':'')+'" data-tab="'+t+'">'+t+'</button>').join('');tabs.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{category=b.dataset.tab;reset();render()});const chooser=isBundle?'<label>Choose your bundle<select id="mixOption">'+bundles.map((x,i)=>'<option value="'+i+'" '+(activeBundle===i?'selected':'')+'>'+x.name+' — '+x.cakes+' mini cake'+(x.cakes>1?'s':'')+' + '+x.bars+' cookie bar'+(x.bars>1?'s':'')+' · $'+x.price+'</option>').join('')+'</select></label>':'<label>Choose box size<select id="mixOption">'+Object.entries(buildPrices).map(([n,p])=>'<option value="'+n+'" '+(buildSize===Number(n)?'selected':'')+'>'+n+' treats · $'+p+'</option>').join('')+'</select></label>';const list=catalog.filter(x=>mixFilter==='all'||x.type===mixFilter);const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.getElementById('builder').innerHTML='<h2 class="sectiontitle">'+(isBundle?'Sweet Bundles ♡':'Build Your Own Treat Box ♡')+'</h2><p class="mix-intro">'+(isBundle?'Our best-loved mini cakes and cookie bars together at a special bundle price.':'Mix and match mini cakes and cookie bars in any combination.')+'</p><div class="mix-choice">'+chooser+'</div><div class="mix-filter"><button data-filter="all" class="'+(mixFilter==='all'?'active':'')+'">All treats</button><button data-filter="cakes" class="'+(mixFilter==='cakes'?'active':'')+'">Mini cakes</button><button data-filter="bars" class="'+(mixFilter==='bars'?'active':'')+'">Cookie bars</button></div><div class="mix-grid">'+list.map(x=>'<article class="mix-tile"><img loading="lazy" src="'+esc(x.img)+'" alt=""><div><strong>'+esc(x.name)+'</strong><small>'+(x.type==='bars'?'Cookie bar':'Mini cake')+'</small></div><div class="qty"><button class="circle" data-mix-minus="'+x.id+'" aria-label="Remove '+esc(x.name)+'" '+(!mixSelected[x.id]?'disabled':'')+'>−</button> '+(mixSelected[x.id]||0)+' <button class="circle" data-mix-plus="'+x.id+'" aria-label="Add '+esc(x.name)+'" '+(total()>=limit||(isBundle&&selectedBy(x.type)>=(x.type==='cakes'?item.cakes:item.bars))?'disabled':'')+'>+</button></div></article>').join('')+'</div><div class="mix-summary"><strong>'+(isBundle?item.name:'Custom Treat Box')+' · $'+price.toFixed(2)+'</strong><p>'+(isBundle?selectedBy('cakes')+'/'+item.cakes+' mini cakes · '+selectedBy('bars')+'/'+item.bars+' cookie bars':total()+'/'+limit+' treats selected')+'</p><p class="hint">Cake Tres Leches upgrades and event packaging are available for mini cake orders separately. Checkout remains disabled.</p><button class="primary" id="mixAdd" '+(total()!==limit?'disabled':'')+'>Add to bag →</button></div>';document.getElementById('mixOption').onchange=e=>{if(isBundle)activeBundle=Number(e.target.value);else buildSize=Number(e.target.value);reset();mixRender()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{mixFilter=b.dataset.filter;mixRender()});document.querySelectorAll('[data-mix-plus]').forEach(b=>b.onclick=()=>{const id=b.dataset.mixPlus,x=catalog.find(x=>x.id===id);if(total()<limit&&(!isBundle||selectedBy(x.type)<(x.type==='cakes'?item.cakes:item.bars))){mixSelected[id]=(mixSelected[id]||0)+1;mixRender()}});document.querySelectorAll('[data-mix-minus]').forEach(b=>b.onclick=()=>{const id=b.dataset.mixMinus;if(mixSelected[id]){mixSelected[id]--;if(!mixSelected[id])delete mixSelected[id];mixRender()}});document.getElementById('mixAdd').onclick=()=>{if(total()!==limit)return;const detail=catalog.filter(x=>mixSelected[x.id]).map(x=>mixSelected[x.id]+'× '+x.name).join(', ');bag.push({name:isBundle?item.name:'Build Your Own '+limit+' Treat Box',detail,price});reset();mixRender();renderBag()}}render=function(){if(mixed.includes(category)){mixRender();return}originalRender();const tabs=document.getElementById('tabs');if(!tabs)return;const extras=mixed.map(t=>'<button class="tab" data-mixed-tab="'+t+'">'+t+'</button>').join('');tabs.insertAdjacentHTML('beforeend',extras);tabs.querySelectorAll('[data-mixed-tab]').forEach(b=>b.onclick=()=>{category=b.dataset.mixedTab;reset();render()});if(category==='Cookie Bars'){document.querySelectorAll('[data-pack]').forEach(b=>{const n=Number(b.dataset.pack);if(!(n in cookiePrices)){b.hidden=true}else{b.textContent=n+' cookie bar'+(n===1?'':'s')+' · $'+cookiePrices[n].toFixed(2)}});const strong=document.getElementById('addBox')?.parentElement?.querySelector('strong');if(strong)strong.textContent=pack+' Cookie Bar'+(pack===1?'':'s')+' · $'+(cookiePrices[pack]??cookiePrices[1]).toFixed(2);const add=document.getElementById('addBox');if(add)add.addEventListener('click',()=>{setTimeout(()=>{const item=bag[bag.length-1];if(item&&item.name.includes('Cookie Bar')){item.price=(cookiePrices[pack]??cookiePrices[1])+(item.eventUpgradePrice||0);renderBag()}},0)},true)}};const oldRenderTabs=renderTabs;renderTabs=function(){oldRenderTabs();};const hero=document.querySelector('.promo-hero');if(hero){const slides=[...hero.querySelectorAll('.promo-slide')];function update(){const idx=slides.findIndex(x=>x.classList.contains('active'));slides.forEach((el,i)=>{el.classList.toggle('feed-above',i<idx);el.classList.toggle('feed-below',i>idx)});}const observer=new MutationObserver(update);slides.forEach(el=>observer.observe(el,{attributes:true,attributeFilter:['class']}));update();const prev=document.getElementById('promoPrev'),next=document.getElementById('promoNext');if(prev){prev.textContent='↑';prev.setAttribute('aria-label','Previous story')}if(next){next.textContent='↓';next.setAttribute('aria-label','Next story')}let startY=null;hero.addEventListener('touchstart',e=>{startY=e.touches[0]?.clientY??null},{passive:true,capture:true});hero.addEventListener('touchend',e=>{if(startY===null)return;const delta=e.changedTouches[0].clientY-startY;startY=null;if(Math.abs(delta)<65||Math.abs(delta)<Math.abs(e.changedTouches[0].clientX-(window.__heroX||e.changedTouches[0].clientX)))return;e.stopPropagation();(delta<0?next:prev)?.click()},{capture:true,passive:true});}render()})();